head.script:
// 토글 바 클릭 시 slide/hide 토글
scwin.fn_slideHide = function (e) {
    scwin.setReturnValue("[group] onclick");
    if (sh_defect.isOpen()) {
        sh_defect.startHide();
        scwin.setReturnValue("-> startHide");
    } else {
        sh_defect.startSlide();
        scwin.setReturnValue("-> startSlide");
    }
};

// 자식 input 이벤트 출력 (onkeyup 은 3회까지 출력 후 ...)
scwin.keyupCount = { input1: 0, input2: 0 };

scwin.resetKeyupCount = function () {
    scwin.keyupCount = { input1: 0, input2: 0 };
};

scwin.printEvent = function (name, evName) {
    if (evName === "onkeyup") {
        if (scwin.keyupCount[name] < 3) {
            scwin.setReturnValue("[" + name + "] onkeyup");
            if (scwin.keyupCount[name] == 2) {
                scwin.setReturnValue("...");
            }
        }
        scwin.keyupCount[name] += 1;
        return;
    }
    scwin.setReturnValue("[" + name + "] " + evName);
};

scwin.ibx_child1_onclick = function (e) { scwin.printEvent("input1", "onclick"); };
scwin.ibx_child1_onfocus = function (e) { scwin.printEvent("input1", "onfocus"); };
scwin.ibx_child1_onkeyup = function (e) { scwin.printEvent("input1", "onkeyup"); };
scwin.ibx_child1_onchange = function (e) { scwin.printEvent("input1", "onchange"); };
scwin.ibx_child2_onclick = function (e) { scwin.printEvent("input2", "onclick"); };
scwin.ibx_child2_onfocus = function (e) { scwin.printEvent("input2", "onfocus"); };
scwin.ibx_child2_onkeyup = function (e) { scwin.printEvent("input2", "onkeyup"); };
scwin.ibx_child2_onchange = function (e) { scwin.printEvent("input2", "onchange"); };

scwin.btn_disabled_true_onclick = function (e) {
    scwin.resetKeyupCount();
    sh_defect.setDisabled(true);
    scwin.setReturnValue("setDisabled(true)");
};

scwin.btn_disabled_false_onclick = function (e) {
    scwin.resetKeyupCount();
    sh_defect.setDisabled(false);
    scwin.setReturnValue("setDisabled(false)");
};

scwin.btn_readonly_true_onclick = function (e) {
    scwin.resetKeyupCount();
    sh_defect.setReadOnly(true);
    scwin.setReturnValue("setReadOnly(true)");
};

scwin.btn_readonly_false_onclick = function (e) {
    scwin.resetKeyupCount();
    sh_defect.setReadOnly(false);
    scwin.setReturnValue("setReadOnly(false)");
};

scwin.btn_check_onclick = function (e) {
    scwin.setReturnValue("[slideHide] getDisabled=" + sh_defect.getDisabled()
        + " / getReadOnly=" + sh_defect.getReadOnly());
    scwin.setReturnValue("[input1] getDisabled=" + ibx_child1.getDisabled()
        + " / getReadOnly=" + ibx_child1.getReadOnly());
    scwin.setReturnValue("[input2] getDisabled=" + ibx_child2.getDisabled()
        + " / getReadOnly=" + ibx_child2.getReadOnly());
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    scwin.resetKeyupCount();
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
